<?php use Lunixi\Sdk\Commerce\Money; ?><!doctype html><html lang="<?= esc(service('request')->getLocale()) ?>"><meta charset="utf-8"><link rel="icon" href="/assets/lunixi.svg" type="image/svg+xml"><title>Lunixi</title><link rel="stylesheet" href="/assets/checkout.css"><main><img src="/assets/lunixi.svg" width="160" alt="Lunixi"><h1><?= esc(lang('Payments.orders')) ?></h1><?php foreach ($orders as $order): ?><article><h2>#<?= (int) $order['id'] ?></h2><p><?= esc(Money::decimal((int) $order['amount'], Money::exponent($order['currency']))) ?> <?= esc($order['currency']) ?> · <?= esc(lang('Payments.state_' . $order['state'])) ?></p><?php if ($order['state'] === 'pending'): ?><form method="post" action="/payments/<?= (int) $order['id'] ?>"><?= csrf_field() ?><button type="submit"><?= esc(lang('Payments.pay')) ?></button></form><?php endif ?></article><?php endforeach ?><form method="post" action="/logout"><?= csrf_field() ?><button type="submit"><?= esc(lang('Payments.logout')) ?></button></form></main></html>
